import { WorkerCacheStorage } from 'synapse-storage/core'
import type { WorkerStorageConfig, WorkerStorageOptions } from 'synapse-storage/core'

interface WorkerStorageOptions {
  channelName?: string       // default: config.name — same channelName ⇒ shared cache
  workerUrl?: string | URL   // custom SharedWorker script (else inline blob)
  requestTimeoutMs?: number  // per-RPC timeout, default 1000 — raise for large initial getAll
}

// WorkerStorageConfig<T> extends AsyncStorageConfig<T> with options?: WorkerStorageOptions

// ── Synchronous storage (MemoryStorage / LocalStorage) ──

todoStorage.set('filter', 'completed')
todoStorage.set('todos', [{ id: 't1', title: 'New', done: false }])

// ── Asynchronous storage (IndexedDBStorage) ──

await todoStorage.set('filter', 'completed')

// ── Synchronous storage ──

todoStorage.update((state) => {
  state.todos.push({ id: 't2', title: 'Buy milk', done: false })
  state.filter = 'active'
})

// A targeted change of a nested element — without manually copying the array:
todoStorage.update((state) => {
  const target = state.todos.find((t) => t.id === 't2')
  if (target) target.done = true
})

// ── Asynchronous storage ──

await todoStorage.update((state) => {
  state.filter = 'completed'
})

// set() — a full replacement of one field.
todoStorage.set('filter', 'active')
todoStorage.set('todos', [])

// update() — several fields atomically, one notification.
todoStorage.update((s) => {
  s.todos.push({ id: 't3', title: 'Task', done: false })
  s.filter = 'all'
})

// Two set() = two notifications:
todoStorage.set('filter', 'active')   // notification 1
todoStorage.set('todos', [])          // notification 2

// The same result via update() = one notification:
todoStorage.update((s) => {
  s.filter = 'active'                  // }
  s.todos = []                         // } one combined notification
})

// Synchronously
todoStorage.reset()

// Asynchronously
await todoStorage.reset()

import { MemoryStorage, Selectors } from 'synapse-storage/core'
import { Dispatcher } from 'synapse-storage/reactive'
import { createSynapse } from 'synapse-storage/utils'

class CounterDispatcher extends Dispatcher<{ count: number }> {
  inc = this.action((store) => store.update((s) => { s.count++ }))
}

class CounterSelectors extends Selectors<{ count: number }> {
  count = this.select((s) => s.count)
}

export const counter = createSynapse({
  storage: () => new MemoryStorage({ name: 'counter', initialState: { count: 0 } }),
  dispatcher: (s) => new CounterDispatcher(s),
  selectors: (s) => new CounterSelectors(s),
})

// ─── Сырые типы ответа API ────────────────────────────────────────────────
// Описывают форму, которую отдаёт PokeAPI, — её мы прячем за мапперами.

interface PokemonListApiResponse {
  count: number
  next: string | null
  results: Array<{ name: string; url: string }>
}

interface PokemonApiResponse {
  id: number
  name: string
  types: Array<{ type: { name: string } }>
  stats: Array<{ stat: { name: string }; base_stat: number }>
  abilities: Array<{ ability: { name: string } }>
  sprites: { front_default: string }
  height: number
  weight: number
}

// ─── ApiClient ──────────────────────────────────────────────────────────────

export const pokemonApiClient = new ApiClient({
  // Хранилище кэша запросов (обязательно).
  storage: new MemoryStorage<Record<string, any>>({
    name: 'pokemon-advanced-api-cache',
    initialState: {},
  }),

  baseQuery: {
    baseUrl: 'https://pokeapi.co/api/v2',
    timeout: 10000,                       // таймаут запроса (мс)
  },

  cache: {
    ttl: 60000,                           // глобальное время жизни кэша (мс)
    invalidateOnError: true,              // инвалидировать кэш при ошибке
  },

  endpoints: async (create) => ({
    // GET — список с query-параметрами
    getList: create<{ limit: number; offset: number }, PokemonListApiResponse>({
      request: (params) => ({
        path: '/pokemon',
        method: 'GET',
        query: params,                    // -> ?limit=12&offset=0
      }),
      cache: { ttl: 120000 },             // свой TTL для этого эндпоинта
      tags: ['pokemon-list'],             // теги для инвалидации
    }),

    // GET — один ресурс по ID (параметр в пути)
    getDetails: create<{ id: number }, PokemonApiResponse>({
      request: ({ id }) => ({
        path: `/pokemon/${id}`,           // -> /pokemon/25
        method: 'GET',
      }),
      cache: true,                        // использует глобальный TTL
      tags: ['pokemon-details'],
    }),
  }),
})

// Инициализация клиента (см. ниже «Жизненный цикл»).
export const initPokemonApi = () => pokemonApiClient.init()

// Тип набора эндпоинтов — отдаётся в эффекты как сервис.
export type PokemonApiEndpoints = ReturnType<typeof pokemonApiClient.getEndpoints>

import type { PokemonBrief, PokemonDetails } from './pokemon.types'

export function mapListResponse(data: PokemonListApiResponse): { list: PokemonBrief[]; hasMore: boolean } {
  const list: PokemonBrief[] = data.results.map((p) => {
    // PokeAPI не отдаёт id в списке — достаём его из url.
    const id = parseInt(p.url.split('/').filter(Boolean).pop()!)
    return {
      id,
      name: p.name,
      sprite: `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`,
    }
  })
  return { list, hasMore: !!data.next }
}

export function mapDetailsResponse(data: PokemonApiResponse): PokemonDetails {
  return {
    id: data.id,
    name: data.name,
    types: data.types.map((t) => t.type.name),
    stats: data.stats.map((s) => ({ name: s.stat.name, value: s.base_stat })),
    abilities: data.abilities.map((a) => a.ability.name),
    sprite: data.sprites.front_default,
    height: data.height,
    weight: data.weight,
  }
}

