    private readonly usersApi: UsersApiEndpoints,       // REST #2
    private readonly socket: ChatSocketService,         // WebSocket-сервис
    private readonly presence$: Observable<PresenceState>, // поток соседнего стора
  ) {
    super()
  }

  // История беседы по выбору (REST #1)
  readonly loadHistory = this.effect((action$, state$, { dispatcher: d }) =>
    action$.pipe(
      ofType(d.openConversation),
      validateMap({
        loadingAction: () => d.loadHistory.loading(),
        errorAction: (err) => d.loadHistory.failure(String(err)),
        apiCall: (action) =>
          fromRequest(this.messagesApi.getHistory.request({ conversationId: action.payload })).pipe(
            apiResult((data) => {
              d.applyHistory(data)
              d.loadHistory.success()
            }),
          ),
      }),
    ),
  )

  // Подтягиваем профили авторов (REST #2)
  readonly loadAuthors = this.effect((action$, state$, { dispatcher: d }) =>
    action$.pipe(
      ofType(d.applyHistory),
      validateMap({
        apiCall: (action) =>
          fromRequest(this.usersApi.getByIds.request({ ids: authorIds(action.payload) })).pipe(
            apiResult((users) => d.applyAuthors(users)),
          ),
      }),
    ),
  )

  // Входящие из сокета вливаются в стор. Диспатч — side-effect через tap
  // (эмиссии эффекта НЕ диспатчатся автоматически — только вызовы d.*).
  readonly incoming = this.effect((action$, state$, { dispatcher: d }) =>
    this.socket.messages$.pipe(tap((msg) => d.messageReceived(msg))),
  )

  // Отправка: экшен → сокет.send
  readonly send = this.effect((action$, state$, { dispatcher: d }) =>
    action$.pipe(
      ofType(d.sendMessage),
      tap((action) => this.socket.send(action.payload)),
    ),
  )

  // Реакция на поток СОСЕДНЕГО стора (presence): отметить онлайн/оффлайн собеседников
  readonly presenceSync = this.effect((action$, state$, { dispatcher: d }) =>
    this.presence$.pipe(tap((presence) => d.applyPresence(presence.online))),
  )

  // Сокет закрываем при уничтожении модуля
  override onDestroy() {
    this.socket.disconnect()
  }
}

import { Dispatcher } from 'synapse-storage/reactive'
import type { PokemonBrief, PokemonDetails, PokemonState } from './pokemon.types'

export class PokemonDispatcher extends Dispatcher<PokemonState> {
  // apiActions — вызываемая группа жизненного цикла запроса (см. dispatcher-detailed)
  readonly loadList = this.apiActions<void>((s) => s.api.listRequest)
  readonly loadDetails = this.apiActions<void>((s) => s.api.detailsRequest)

  // signal — чистый сигнал-намерение без записи в состояние (его обработает эффект)
  readonly loadMore = this.signal<void>('Подгрузить следующую страницу')

  // action — намерение, которое само меняет состояние
  readonly selectPokemon = this.action((store, id: number | null) => {
    store.update((s) => {
      s.selectedPokemonId = id
      if (id === null) s.selectedPokemon = null
    })
    return id
  })

  readonly setSearchQuery = this.action((store, query: string) => {
    store.set('searchQuery', query)
    return query
  })

  readonly toggleFavorite = this.action((store, id: number) => {
    store.update((s) => {
      const idx = s.favorites.indexOf(id)
      if (idx >= 0) s.favorites.splice(idx, 1)
      else s.favorites.push(id)
    })
    return id
  })

  // Экшены, которыми эффект записывает результат запроса в состояние
  readonly applyPokemonList = this.action((store, data: { list: PokemonBrief[]; hasMore: boolean; append: boolean }) =>
    store.update((s) => {
      s.pokemonList = data.append ? [...s.pokemonList, ...data.list] : data.list
      s.offset = s.pokemonList.length
      s.hasMore = data.hasMore
    }),
  )

  readonly applyPokemonDetails = this.action((store, details: PokemonDetails) =>
    store.update((s) => {
      s.selectedPokemon = details
    }),
  )

  // watcher — реактивно отслеживает срез состояния
  readonly watchFavoriteCount = this.watcher({
    selector: (s) => s.favorites.length,
    meta: { description: 'отслеживание кол-ва избранных' },
    notifyAfterSubscribe: true,
  })
}

